mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1 FROM crm_opportunity WHERE tenant_id = #{tenantId} AND (stage = #{stageCode} OR last_stage = #{stageCode})
) OR EXISTS (
    SELECT 1 FROM crm_opportunity_stage_history WHERE tenant_id = #{tenantId} AND (from_stage = #{stageCode} OR to_stage = #{stageCode})
) THEN 1 ELSE 0 END

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM crm_follow_up WHERE tenant_id = #{tenantId} AND opportunity_id = #{opportunityId}
        AND customer_id = #{customerId} AND deleted = 0 AND follow_up_time <= NOW() AND TRIM(content) != ''
) OR EXISTS (
    SELECT 1 FROM crm_activity WHERE tenant_id = #{tenantId} AND biz_type = 'OPPORTUNITY' AND biz_id = #{opportunityId}
        AND deleted = 0 AND status = 'COMPLETED' AND end_time <= NOW()
) THEN 1 ELSE 0 END
